    static func iconView(_ path: String, size: CGFloat) -> some View {
        SVGPathShape(pathData: path, viewBox: viewBox)
            .fill(.primary)
            .frame(width: size, height: size)
    }

    static func drawInContext(_ ctx: CGContext, path: String, in rect: CGRect) {
        let cgPath = SVGPathShape.parse(path)
        let scale = min(rect.width / viewBox.width, rect.height / viewBox.height)
        ctx.saveGState()
        ctx.translateBy(x: rect.minX, y: rect.maxY)
        ctx.scaleBy(x: scale, y: -scale)
        ctx.addPath(cgPath)
        ctx.setFillColor(NSColor.black.cgColor)
        ctx.fillPath()
        ctx.restoreGState()
    }
